  "project_id": "27cb7e18ef0643fa9f07",
  "query": "select n.nspname as schema_name, c.relname as table_name, c.relrowsecurity as rls_enabled, c.relforcerowsecurity as rls_forced, has_table_privilege('authenticated', c.oid, 'select') as authenticated_select, has_table_privilege('authenticated', c.oid, 'insert') as authenticated_insert, has_table_privilege('authenticated', c.oid, 'update') as authenticated_update, has_table_privilege('authenticated', c.oid, 'delete') as authenticated_delete from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('r','p') and n.nspname='public' order by c.relname;"
}

