{
  "project_id": "27cb7e18ef0643fa9f07",
  "query": "select n.nspname as schema_name, c.relname as table_name, grantee, privilege_type from information_schema.role_table_grants g join pg_class c on c.relname=g.table_name join pg_namespace n on n.oid=c.relnamespace and n.nspname=g.table_schema where g.grantee in ('anon','authenticated') and g.table_schema not in ('pg_catalog','information_schema','auth') order by n.nspname, c.relname, grantee, privilege_type;"
}

